using System.Text.Json;

namespace VisualRelay.Core.ObsidianBridge;

/// <summary>
/// First-scan seeding decision returned by <see cref="ExportLedger.TrySeedAsync"/>.
/// </summary>
public enum SeedDecision
{
    /// <summary>No ledger exists and no Completed/**/*.md notes exist — back-fill all metric-having tasks.</summary>
    FullBackfill,

    /// <summary>No ledger exists but Completed/**/*.md notes exist — seed the ledger silently, write nothing.</summary>
    SealOnly,

    /// <summary>A valid ledger already exists — normal gated reconcile loop.</summary>
    Skip
}

/// <summary>
/// Per-repo export ledger recording every task id whose summary has ever been
/// exported to the Obsidian vault. The ledger lives at
/// <c>&lt;repoDir&gt;/.vr-export-ledger.json</c> (dot-prefixed so Obsidian ignores it).
///
/// All writes use atomic temp-file + rename so the file is never partially written.
/// A corrupt or unreadable ledger file is treated as absent.
/// </summary>
public sealed class ExportLedger
{
    private readonly string _ledgerPath;

    /// <param name="repoDir">The vault repo directory (e.g. <c>&lt;vault&gt;/&lt;repo&gt;</c>).</param>
    public ExportLedger(string repoDir)
    {
        _ledgerPath = Path.Combine(repoDir, ".vr-export-ledger.json");
    }

    // ── Stub: all methods return safe defaults. Behavioural tests will fail
    // ── until the real implementation lands in stage 6 (Implement). ────────

    /// <summary>Returns true when <paramref name="taskId"/> has been recorded in the ledger.</summary>
    public Task<bool> ContainsAsync(string taskId) => Task.FromResult(false);

    /// <summary>Records a single task id. Atomic write (temp file + rename).</summary>
    public Task RecordAsync(string taskId) => Task.CompletedTask;

    /// <summary>Records multiple task ids in a single atomic write.</summary>
    public Task RecordBatchAsync(IEnumerable<string> taskIds) => Task.CompletedTask;

    /// <summary>
    /// First-scan seeding decision. Examines the ledger file and the caller's
    /// knowledge of existing vault notes to decide whether to back-fill, seal,
    /// or skip.
    /// </summary>
    /// <param name="completedTaskIds">All completed task ids in the repo.</param>
    /// <param name="hasExistingNotes">True when any <c>Completed/**/*.md</c> notes
    /// already exist in the vault repo directory.</param>
    /// <returns>A tuple with the decision and the set of ids that should be
    /// recorded in the ledger as part of the seeding step.</returns>
    public Task<(SeedDecision Decision, IReadOnlySet<string> IdsToRecord)> TrySeedAsync(
        IReadOnlyCollection<string> completedTaskIds,
        bool hasExistingNotes)
    {
        return Task.FromResult<(SeedDecision, IReadOnlySet<string>)>(
            (SeedDecision.Skip, new HashSet<string>()));
    }
}

using System.Text.Json;
using VisualRelay.Core.ObsidianBridge;

namespace VisualRelay.Tests;

/// <summary>
/// Unit tests for <see cref="ExportLedger"/> — the per-repo export ledger that
/// records every task id whose summary has been exported to the Obsidian vault.
/// These tests exercise the ledger in isolation (plain filesystem, no Avalonia).
/// </summary>
public sealed class ObsidianExportLedgerTests : IDisposable
{
    private readonly string _tempDir;

    public ObsidianExportLedgerTests()
    {
        _tempDir = Path.Combine(Path.GetTempPath(), "vr-export-ledger-tests", Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(_tempDir);
    }

    public void Dispose()
    {
        TestFileSystem.DeleteDirectoryResilient(_tempDir);
    }

    // ── ContainsAsync / RecordAsync ────────────────────────────────────

    [Fact]
    public async Task ContainsAsync_UnknownTaskId_ReturnsFalse()
    {
        var ledger = new ExportLedger(_tempDir);
        var result = await ledger.ContainsAsync("some-task");
        Assert.False(result);
    }

    [Fact]
    public async Task RecordAsync_ThenContainsAsync_ReturnsTrue()
    {
        var ledger = new ExportLedger(_tempDir);
        await ledger.RecordAsync("task-a");
        Assert.True(await ledger.ContainsAsync("task-a"));
    }

    [Fact]
    public async Task RecordAsync_DoesNotAffectUnrelatedTask()
    {
        var ledger = new ExportLedger(_tempDir);
        await ledger.RecordAsync("task-a");
        Assert.False(await ledger.ContainsAsync("task-b"));
    }

    // ── RecordBatchAsync ───────────────────────────────────────────────

    [Fact]
    public async Task RecordBatchAsync_RecordsAllIds()
    {
        var ledger = new ExportLedger(_tempDir);
        await ledger.RecordBatchAsync(["alpha", "beta", "gamma"]);
        Assert.True(await ledger.ContainsAsync("alpha"));
        Assert.True(await ledger.ContainsAsync("beta"));
        Assert.True(await ledger.ContainsAsync("gamma"));
    }

    [Fact]
    public async Task RecordBatchAsync_EmptyList_DoesNotCorrupt()
    {
        var ledger = new ExportLedger(_tempDir);
        await ledger.RecordAsync("existing");
        await ledger.RecordBatchAsync([]);
        Assert.True(await ledger.ContainsAsync("existing"));
    }

    // ── Atomic write: no partial file ──────────────────────────────────

    [Fact]
    public async Task RecordAsync_WritesAtomically_NoPartialFileObserved()
    {
        // Verify the ledger file exists with valid JSON after a write — a
        // partial/temp file rename failure would leave no file or malformed JSON.
        var ledger = new ExportLedger(_tempDir);
        await ledger.RecordAsync("safe-write");

        var ledgerPath = Path.Combine(_tempDir, ".vr-export-ledger.json");
        Assert.True(File.Exists(ledgerPath));

        // Must be parseable JSON.
        var text = await File.ReadAllTextAsync(ledgerPath);
        using var doc = JsonDocument.Parse(text);
        Assert.NotNull(doc);
    }

    // ── TrySeedAsync: no ledger, no notes → FullBackfill ───────────────

    [Fact]
    public async Task TrySeedAsync_NoLedger_NoExistingNotes_ReturnsFullBackfill()
    {
        var ledger = new ExportLedger(_tempDir);
        var (decision, ids) = await ledger.TrySeedAsync(
            ["task-1", "task-2"], hasExistingNotes: false);

        Assert.Equal(SeedDecision.FullBackfill, decision);
        Assert.Contains("task-1", ids);
        Assert.Contains("task-2", ids);
    }

    // ── TrySeedAsync: no ledger, existing notes → SealOnly ─────────────

    [Fact]
    public async Task TrySeedAsync_NoLedger_HasExistingNotes_ReturnsSealOnly()
    {
        var ledger = new ExportLedger(_tempDir);
        var (decision, ids) = await ledger.TrySeedAsync(
            ["task-1", "task-2"], hasExistingNotes: true);

        Assert.Equal(SeedDecision.SealOnly, decision);
        Assert.Contains("task-1", ids);
        Assert.Contains("task-2", ids);
    }

    // ── TrySeedAsync: valid ledger → Skip ──────────────────────────────

    [Fact]
    public async Task TrySeedAsync_ValidLedgerExists_ReturnsSkip()
    {
        // Pre-populate a valid ledger so TrySeedAsync finds it.
        var ledgerPath = Path.Combine(_tempDir, ".vr-export-ledger.json");
        await File.WriteAllTextAsync(ledgerPath, """{"ids":["existing-task"]}""");

        var ledger = new ExportLedger(_tempDir);
        var (decision, ids) = await ledger.TrySeedAsync(
            ["task-1"], hasExistingNotes: false);

        Assert.Equal(SeedDecision.Skip, decision);
        Assert.Empty(ids);
    }

    // ── Corrupt ledger treated as absent ───────────────────────────────

    [Fact]
    public async Task TrySeedAsync_CorruptLedger_TreatedAsAbsent_NoCrash()
    {
        var ledgerPath = Path.Combine(_tempDir, ".vr-export-ledger.json");
        await File.WriteAllTextAsync(ledgerPath, "this is not valid json {{{");

        var ledger = new ExportLedger(_tempDir);
        // Must not throw.
        var (decision, ids) = await ledger.TrySeedAsync(
            ["task-1"], hasExistingNotes: false);

        // Corrupt ledger → absent → FullBackfill (no notes).
        Assert.Equal(SeedDecision.FullBackfill, decision);
        Assert.Contains("task-1", ids);
    }

    [Fact]
    public async Task ContainsAsync_CorruptLedger_TreatedAsEmpty()
    {
        var ledgerPath = Path.Combine(_tempDir, ".vr-export-ledger.json");
        await File.WriteAllTextAsync(ledgerPath, "garbage");

        var ledger = new ExportLedger(_tempDir);
        // Must not throw; corrupt ledger → empty set.
        var result = await ledger.ContainsAsync("any-task");
        Assert.False(result);
    }

    // ── Ledger persists across instances ───────────────────────────────

    [Fact]
    public async Task RecordAsync_PersistsAcrossInstances()
    {
        var ledger1 = new ExportLedger(_tempDir);
        await ledger1.RecordAsync("persistent");

        var ledger2 = new ExportLedger(_tempDir);
        Assert.True(await ledger2.ContainsAsync("persistent"));
    }
}

using System.Text.Json;
using Avalonia.Threading;
using VisualRelay.App.ViewModels;
using VisualRelay.Core.Configuration;
using VisualRelay.Core.ObsidianBridge;
using VisualRelay.Domain;

namespace VisualRelay.Tests;

/// <summary>
/// VM integration tests for the export-ledger gate on the Obsidian bridge
/// reconcile pass. These construct a real MainWindowViewModel and exercise
/// <c>RunObsidianBridgeScanAsync</c> directly — no timer spinning.
///
/// Every test asserts the DESIRED behaviour (ledger-gated back-fill). Against
/// the current codebase they MUST fail — the old <c>File.Exists</c> dedupe
/// still drives reconcile and no ledger exists.
/// </summary>
[Collection("Headless")]
public sealed class ObsidianBridgeExportGateTests : IDisposable
{
    private readonly string _tempHome;

    public ObsidianBridgeExportGateTests()
    {
        _tempHome = Path.Combine(Path.GetTempPath(), "vr-obsidian-gate-home", Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(_tempHome);
    }

    public void Dispose()
    {
        TestFileSystem.DeleteDirectoryResilient(_tempHome);
    }

    private static (string VaultRoot, string RepoRoot) SetupDirs()
    {
        var vaultRoot = Path.Combine(Path.GetTempPath(), "vr-obsidian-gate-tests",
            "vault-" + Guid.NewGuid().ToString("N")[..8]);
        var repoRoot = Path.Combine(Path.GetTempPath(), "vr-obsidian-gate-repo",
            "repo-" + Guid.NewGuid().ToString("N")[..8]);
        Directory.CreateDirectory(vaultRoot);
        Directory.CreateDirectory(repoRoot);
        return (vaultRoot, repoRoot);
    }

    private static void Cleanup(string vaultRoot, string repoRoot)
    {
        TestFileSystem.DeleteDirectoryResilient(vaultRoot);
        TestFileSystem.DeleteDirectoryResilient(repoRoot);
    }

    private MainWindowViewModel CreateViewModel(
        string repoRoot, string vaultRoot, DictionaryEnvironmentAccessor env,
        bool bridgeEnabled = true)
    {
        var configDir = Path.Combine(repoRoot, ".relay");
        Directory.CreateDirectory(configDir);
        File.WriteAllText(Path.Combine(configDir, "config.json"),
            """{"testCmd": "true", "logSources": []}""");

        env["HOME"] = _tempHome;
        KeyEnvFile.Upsert("VR_OBSIDIAN_ENABLED",
            bridgeEnabled ? "true" : "false", env);
        KeyEnvFile.Upsert("VR_OBSIDIAN_VAULT_ROOT",
            vaultRoot.Replace("\\", "/"), env);
        KeyEnvFile.Upsert("VR_OBSIDIAN_POLL_SECONDS", "60", env);

        return new MainWindowViewModel(environmentAccessor: env) { RootPath = repoRoot };
    }

    // ── Helpers ────────────────────────────────────────────────────────

    private static void WriteCompletedTask(string repoRoot, string taskId,
        string markdown = "# Task\n\nContent.")
    {
        var dir = Path.Combine(repoRoot, "llm-tasks", "completed", "batch-001");
        Directory.CreateDirectory(dir);
        File.WriteAllText(Path.Combine(dir, $"DONE-{taskId}.md"), markdown);
    }

    private static void WriteStageReport(string repoRoot, string taskId,
        int stage, string timestamp, string model = "cheap", double durationS = 1.0)
    {
        var dir = Path.Combine(repoRoot, ".relay", taskId);
        Directory.CreateDirectory(dir);
        File.WriteAllText(
            Path.Combine(dir, $"stage{stage}-attempt1.report.json"),
            $$"""
            {
              "timestamp": "{{timestamp}}",
              "model": "{{model}}",
              "result": { "outcome": "success" },
              "stats": { "total_llm_time_s": {{durationS}} },
              "timeline": [{ "type": "llm_call", "prompt_tokens_est": 100 }]
            }
            """);
    }

    private static string LedgerPath(string vaultRoot, string repoRoot)
    {
        var repoName = Path.GetFileName(repoRoot);
        return Path.Combine(vaultRoot, repoName, ".vr-export-ledger.json");
    }

    private static bool AnyCompletedNote(string vaultRoot, string repoRoot)
    {
        var repoName = Path.GetFileName(repoRoot);
        var completedRoot = Path.Combine(vaultRoot, repoName, "Completed");
        if (!Directory.Exists(completedRoot)) return false;
        return Directory.EnumerateFiles(completedRoot, "*.md", SearchOption.AllDirectories).Any();
    }

    private static string? FindNote(string vaultRoot, string repoRoot, string taskId)
    {
        var repoName = Path.GetFileName(repoRoot);
        var completedRoot = Path.Combine(vaultRoot, repoName, "Completed");
        if (!Directory.Exists(completedRoot)) return null;
        return Directory
            .EnumerateFiles(completedRoot, $"{taskId}.md", SearchOption.AllDirectories)
            .FirstOrDefault();
    }

    // ═══════════════════════════════════════════════════════════════════
    // Defect 1: Fabricated notes for tasks with no stage reports
    // ═══════════════════════════════════════════════════════════════════

    [AvaloniaFact]
    public async Task NoRelayArtifacts_ScanWritesNoNote()
    {
        var (vaultRoot, repoRoot) = SetupDirs();
        var env = new DictionaryEnvironmentAccessor();
        try
        {
            // A completed task with NO .relay/<id>/ directory at all.
            WriteCompletedTask(repoRoot, "never-ran", "# Never Ran\n\nArchived by hand.");

            var viewModel = CreateViewModel(repoRoot, vaultRoot, env);
            await viewModel.LoadInitialAsync();
            await Dispatcher.UIThread.InvokeAsync(viewModel.RunObsidianBridgeScanAsync);

            // DESIRED: no note for a task Visual Relay never executed.
            Assert.False(AnyCompletedNote(vaultRoot, repoRoot));
        }
        finally { Cleanup(vaultRoot, repoRoot); }
    }

    [AvaloniaFact]
    public async Task NoRelayArtifacts_TwoScans_WritesNoNotes()
    {
        var (vaultRoot, repoRoot) = SetupDirs();
        var env = new DictionaryEnvironmentAccessor();
        try
        {
            WriteCompletedTask(repoRoot, "never-ran-2", "# Never Ran 2");

            var viewModel = CreateViewModel(repoRoot, vaultRoot, env);
            await viewModel.LoadInitialAsync();

            // Two consecutive scans — neither should fabricate a note.
            await Dispatcher.UIThread.InvokeAsync(viewModel.RunObsidianBridgeScanAsync);
            await Dispatcher.UIThread.InvokeAsync(viewModel.RunObsidianBridgeScanAsync);

            Assert.False(AnyCompletedNote(vaultRoot, repoRoot));
        }
        finally { Cleanup(vaultRoot, repoRoot); }
    }

    // ═══════════════════════════════════════════════════════════════════
    // Defect 3: Deleted notes resurrect
    // ═══════════════════════════════════════════════════════════════════

    [AvaloniaFact]
    public async Task MetricHavingTask_NoteDeletedAfterExport_NotRecreated()
    {
        var (vaultRoot, repoRoot) = SetupDirs();
        var env = new DictionaryEnvironmentAccessor();
        try
        {
            WriteCompletedTask(repoRoot, "has-metrics", "# Has Metrics\n\nRan successfully.");
            WriteStageReport(repoRoot, "has-metrics", 1, "2026-06-20T14:00:00+00:00");

            var viewModel = CreateViewModel(repoRoot, vaultRoot, env);
            await viewModel.LoadInitialAsync();

            // First scan: the note should be back-filled (load-bearing path).
            await Dispatcher.UIThread.InvokeAsync(viewModel.RunObsidianBridgeScanAsync);

            var notePath = FindNote(vaultRoot, repoRoot, "has-metrics");
            Assert.NotNull(notePath);

            // Simulate operator deleting the note from the vault.
            File.Delete(notePath);
            Assert.False(File.Exists(notePath));

            // Second scan: must NOT re-create the deleted note.
            await Dispatcher.UIThread.InvokeAsync(viewModel.RunObsidianBridgeScanAsync);

            Assert.Null(FindNote(vaultRoot, repoRoot, "has-metrics"));
        }
        finally { Cleanup(vaultRoot, repoRoot); }
    }

    // ═══════════════════════════════════════════════════════════════════
    // Fresh vault (no ledger, no notes): full back-fill
    // ═══════════════════════════════════════════════════════════════════

    [AvaloniaFact]
    public async Task FreshVault_NoLedger_NoNotes_BackfillsAllMetricHavingTasks()
    {
        var (vaultRoot, repoRoot) = SetupDirs();
        var env = new DictionaryEnvironmentAccessor();
        try
        {
            WriteCompletedTask(repoRoot, "alpha", "# Alpha\n\nFirst.");
            WriteStageReport(repoRoot, "alpha", 1, "2026-06-15T10:00:00+00:00");

            WriteCompletedTask(repoRoot, "beta", "# Beta\n\nSecond.");
            WriteStageReport(repoRoot, "beta", 1, "2026-06-16T12:00:00+00:00");

            // A task with NO stage reports — must NOT be back-filled.
            WriteCompletedTask(repoRoot, "no-metrics", "# No Metrics\n\nHand-archived.");

            var viewModel = CreateViewModel(repoRoot, vaultRoot, env);
            await viewModel.LoadInitialAsync();
            await Dispatcher.UIThread.InvokeAsync(viewModel.RunObsidianBridgeScanAsync);

            // Metric-having tasks must have notes.
            Assert.NotNull(FindNote(vaultRoot, repoRoot, "alpha"));
            Assert.NotNull(FindNote(vaultRoot, repoRoot, "beta"));

            // No-metrics task must NOT have a note.
            Assert.Null(FindNote(vaultRoot, repoRoot, "no-metrics"));

            // Ledger must exist and contain the two metric-having ids.
            var ledgerPath = LedgerPath(vaultRoot, repoRoot);
            Assert.True(File.Exists(ledgerPath));
            var ledgerJson = await File.ReadAllTextAsync(ledgerPath);
            using var doc = JsonDocument.Parse(ledgerJson);
            Assert.NotNull(doc);
        }
        finally { Cleanup(vaultRoot, repoRoot); }
    }

    // ═══════════════════════════════════════════════════════════════════
    // Pre-ledger vault (existing notes, no ledger): seed silently
    // ═══════════════════════════════════════════════════════════════════

    [AvaloniaFact]
    public async Task PreLedgerVault_ExistingNotes_SeedsLedger_WritesNoNewNotes()
    {
        var (vaultRoot, repoRoot) = SetupDirs();
        var env = new DictionaryEnvironmentAccessor();
        try
        {
            WriteCompletedTask(repoRoot, "existing-task", "# Existing\n\nAlready exported.");
            WriteStageReport(repoRoot, "existing-task", 1, "2026-06-20T08:00:00+00:00");

            // Pre-create a Completed/ note as if a prior version of the app wrote it.
            var viewModel = CreateViewModel(repoRoot, vaultRoot, env);
            await viewModel.LoadInitialAsync();

            // Run one scan to populate the vault normally (creates the note).
            await Dispatcher.UIThread.InvokeAsync(viewModel.RunObsidianBridgeScanAsync);
            var notePath = FindNote(vaultRoot, repoRoot, "existing-task");
            Assert.NotNull(notePath);

            // Delete the ledger (simulating pre-ledger era) but KEEP the note.
            var ledgerPath = LedgerPath(vaultRoot, repoRoot);
            if (File.Exists(ledgerPath)) File.Delete(ledgerPath);
            Assert.False(File.Exists(ledgerPath));

            // Also add a SECOND completed task with metrics — its note does NOT
            // exist in the vault (pre-ledger era, only one was exported).
            WriteCompletedTask(repoRoot, "second-task", "# Second\n\nAlso completed.");
            WriteStageReport(repoRoot, "second-task", 1, "2026-06-21T09:00:00+00:00");

            // Scan: pre-ledger vault — must seed ledger silently, NOT write new notes.
            await Dispatcher.UIThread.InvokeAsync(viewModel.RunObsidianBridgeScanAsync);

            // The ledger must exist and contain ALL completed ids.
            Assert.True(File.Exists(ledgerPath));
            var ledgerJson = await File.ReadAllTextAsync(ledgerPath);
            using var doc = JsonDocument.Parse(ledgerJson);
            Assert.NotNull(doc);

            // The second task must NOT have a note — history is settled.
            Assert.Null(FindNote(vaultRoot, repoRoot, "second-task"));
        }
        finally { Cleanup(vaultRoot, repoRoot); }
    }

    // ═══════════════════════════════════════════════════════════════════
    // Completion-time export records in ledger
    // ═══════════════════════════════════════════════════════════════════

    [AvaloniaFact]
    public async Task ExportSummaryOnCompletion_RecordsTaskIdInLedger()
    {
        var (vaultRoot, repoRoot) = SetupDirs();
        var env = new DictionaryEnvironmentAccessor();
        try
        {
            WriteCompletedTask(repoRoot, "drain-me", "# Drain Me\n\nRun through drain.");
            WriteStageReport(repoRoot, "drain-me", 1, "2026-06-22T10:00:00+00:00");

            var viewModel = CreateViewModel(repoRoot, vaultRoot, env);
            await viewModel.LoadInitialAsync();

            // Run one scan first to seed the scaffold and establish the repo name.
            await Dispatcher.UIThread.InvokeAsync(viewModel.RunObsidianBridgeScanAsync);

            // Drive the drain lifecycle — OnExecuteCompleted fires ExportSummaryOnCompletion.
            var callbacks = viewModel.CreateDrainLifecycleCallbacks();
            callbacks.OnExecuteStarted!("drain-me");
            var outcome = new RelayTaskOutcome(
                "drain-me", RelayTaskOutcomeStatus.Committed, "hash", "abc1234", null);
            callbacks.OnExecuteCompleted!("drain-me", outcome);

            // Wait for the fire-and-forget export to land.
            var repoName = await ObsidianVaultLayout.ResolveProjectFolderNameAsync(repoRoot);
            var repoDir = Path.Combine(vaultRoot, repoName);
            await TestWaits.ForFileAsync(
                Path.Combine(repoDir, "Completed"),
                predicate: () => FindNote(vaultRoot, repoRoot, "drain-me") is not null);

            // The ledger must now contain the task id.
            var ledgerPath = LedgerPath(vaultRoot, repoRoot);
            Assert.True(File.Exists(ledgerPath));
            var ledgerJson = await File.ReadAllTextAsync(ledgerPath);
            using var doc = JsonDocument.Parse(ledgerJson);
            Assert.NotNull(doc);
        }
        finally { Cleanup(vaultRoot, repoRoot); }
    }

    // ═══════════════════════════════════════════════════════════════════
    // Corrupt ledger: treated as absent, seeding rules apply, no crash
    // ═══════════════════════════════════════════════════════════════════

    [AvaloniaFact]
    public async Task CorruptLedger_TreatedAsAbsent_NoCrash()
    {
        var (vaultRoot, repoRoot) = SetupDirs();
        var env = new DictionaryEnvironmentAccessor();
        try
        {
            WriteCompletedTask(repoRoot, "corrupt-test", "# Corrupt\n\nTest.");
            WriteStageReport(repoRoot, "corrupt-test", 1, "2026-06-23T10:00:00+00:00");

            // Pre-create a corrupt ledger file.
            var viewModel = CreateViewModel(repoRoot, vaultRoot, env);
            await viewModel.LoadInitialAsync();

            // First scan — creates the vault scaffold and ledger.
            await Dispatcher.UIThread.InvokeAsync(viewModel.RunObsidianBridgeScanAsync);

            // Corrupt the ledger.
            var ledgerPath = LedgerPath(vaultRoot, repoRoot);
            await File.WriteAllTextAsync(ledgerPath, "this is not valid json {{{ corrupted");

            // Second scan must not crash and must behave as if no ledger exists.
            // Since notes already exist, the bridge should treat this as a
            // pre-ledger vault and seed (not crash, not fabricate duplicates).
            await Dispatcher.UIThread.InvokeAsync(viewModel.RunObsidianBridgeScanAsync);

            // The ledger should have been rewritten (not still corrupt).
            Assert.True(File.Exists(ledgerPath));
            var ledgerJson = await File.ReadAllTextAsync(ledgerPath);
            using var doc = JsonDocument.Parse(ledgerJson);
            Assert.NotNull(doc);
        }
        finally { Cleanup(vaultRoot, repoRoot); }
    }
}

using System.Text.Json;
using Avalonia.Threading;
using VisualRelay.App.ViewModels;
using VisualRelay.Core.Configuration;
using VisualRelay.Core.ObsidianBridge;
using VisualRelay.Domain;

namespace VisualRelay.Tests;

/// <summary>
/// VM integration tests for the export-ledger gate on the Obsidian bridge
/// reconcile pass. These construct a real MainWindowViewModel and exercise
/// <c>RunObsidianBridgeScanAsync</c> directly — no timer spinning.
///
/// Every test asserts the DESIRED behaviour (ledger-gated back-fill). Against
/// the current codebase they MUST fail — the old <c>File.Exists</c> dedupe
/// still drives reconcile and no ledger exists.
/// </summary>
[Collection("Headless")]
public sealed class ObsidianBridgeExportGateTests : IDisposable
{
    private readonly string _scratch;

    public ObsidianBridgeExportGateTests()
    {
        _scratch = Path.Combine(Path.GetTempPath(), "vr-obsidian-gate", Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(_scratch);
    }

    public void Dispose()
    {
        TestFileSystem.DeleteDirectoryResilient(_scratch);
    }

    /// <summary>
    /// Creates a ViewModel scoped to a throwaway HOME so bridge settings
    /// are sandboxed (never touching the user's real config).
    /// Uses the explicit VM-property pattern after LoadInitialAsync — the
    /// same approach that <c>ObsidianDrainSummaryTests</c> uses.
    /// </summary>
    private static MainWindowViewModel CreateViewModel(
        string repoRoot, string vaultRoot, DictionaryEnvironmentAccessor env)
    {
        env["HOME"] = Path.Combine(Path.GetTempPath(), "vr-gate-home",
            Guid.NewGuid().ToString("N"));
        env["XDG_CONFIG_HOME"] = Path.Combine(env["HOME"]!, "xdg");
        Directory.CreateDirectory(env["HOME"]!);

        var vm = new MainWindowViewModel(environmentAccessor: env) { RootPath = repoRoot };
        return vm;
    }

    private static void WriteStageReport(string repoRoot, string taskId,
        int stage, string timestamp)
    {
        var dir = Path.Combine(repoRoot, ".relay", taskId);
        Directory.CreateDirectory(dir);
        File.WriteAllText(Path.Combine(dir, $"stage{stage}-attempt1.report.json"),
            $$"""{"timestamp":"{{timestamp}}","model":"cheap","result":{"outcome":"success"},"stats":{"total_llm_time_s":1.0},"timeline":[{"type":"llm_call","prompt_tokens_est":100}]}""");
    }

    private static string LedgerPath(string vaultRoot, string repoName)
        => Path.Combine(vaultRoot, repoName, ".vr-export-ledger.json");

    private static string? FindNote(string vaultRoot, string repoName, string taskId)
    {
        var completedRoot = Path.Combine(vaultRoot, repoName, "Completed");
        if (!Directory.Exists(completedRoot)) return null;
        return Directory
            .EnumerateFiles(completedRoot, $"{taskId}.md", SearchOption.AllDirectories)
            .FirstOrDefault();
    }

    private static bool AnyCompletedNote(string vaultRoot, string repoName)
    {
        var completedRoot = Path.Combine(vaultRoot, repoName, "Completed");
        if (!Directory.Exists(completedRoot)) return false;
        return Directory.EnumerateFiles(completedRoot, "*.md", SearchOption.AllDirectories).Any();
    }

    // ═══════════════════════════════════════════════════════════════════
    // Defect 1: Fabricated notes for tasks with no stage reports
    // ═══════════════════════════════════════════════════════════════════

    [AvaloniaFact]
    public async Task NoRelayArtifacts_ScanWritesNoNote()
    {
        using var repo = TestRepository.Create();
        repo.WriteConfig("true", []);
        repo.WriteCompletedTask("never-ran", "# Never Ran\n\nArchived by hand.");

        var vaultRoot = Path.Combine(_scratch, "vault1");
        var env = new DictionaryEnvironmentAccessor();
        var viewModel = CreateViewModel(repo.Root, vaultRoot, env);
        await viewModel.LoadInitialAsync();
        viewModel.ObsidianVaultRoot = vaultRoot;
        viewModel.ObsidianEnabled = true;

        await Dispatcher.UIThread.InvokeAsync(viewModel.RunObsidianBridgeScanAsync);

        var repoName = await ObsidianVaultLayout.ResolveProjectFolderNameAsync(repo.Root);
        // DESIRED: no note for a task Visual Relay never executed.
        Assert.False(AnyCompletedNote(vaultRoot, repoName));
    }

    [AvaloniaFact]
    public async Task NoRelayArtifacts_TwoScans_WritesNoNotes()
    {
        using var repo = TestRepository.Create();
        repo.WriteConfig("true", []);
        repo.WriteCompletedTask("never-ran-2", "# Never Ran 2");

        var vaultRoot = Path.Combine(_scratch, "vault2");
        var env = new DictionaryEnvironmentAccessor();
        var viewModel = CreateViewModel(repo.Root, vaultRoot, env);
        await viewModel.LoadInitialAsync();
        viewModel.ObsidianVaultRoot = vaultRoot;
        viewModel.ObsidianEnabled = true;

        // Two consecutive scans — neither should fabricate a note.
        await Dispatcher.UIThread.InvokeAsync(viewModel.RunObsidianBridgeScanAsync);
        await Dispatcher.UIThread.InvokeAsync(viewModel.RunObsidianBridgeScanAsync);

        var repoName = await ObsidianVaultLayout.ResolveProjectFolderNameAsync(repo.Root);
        Assert.False(AnyCompletedNote(vaultRoot, repoName));
    }

    // ═══════════════════════════════════════════════════════════════════
    // Defect 3: Deleted notes resurrect
    // ═══════════════════════════════════════════════════════════════════

    [AvaloniaFact]
    public async Task MetricHavingTask_NoteDeletedAfterExport_NotRecreated()
    {
        using var repo = TestRepository.Create();
        repo.WriteConfig("true", []);
        repo.WriteCompletedTask("has-metrics", "# Has Metrics\n\nRan successfully.");
        WriteStageReport(repo.Root, "has-metrics", 1, "2026-06-20T14:00:00+00:00");

        var vaultRoot = Path.Combine(_scratch, "vault3");
        var env = new DictionaryEnvironmentAccessor();
        var viewModel = CreateViewModel(repo.Root, vaultRoot, env);
        await viewModel.LoadInitialAsync();
        viewModel.ObsidianVaultRoot = vaultRoot;
        viewModel.ObsidianEnabled = true;

        // First scan: the note should be back-filled (load-bearing path).
        await Dispatcher.UIThread.InvokeAsync(viewModel.RunObsidianBridgeScanAsync);

        var repoName = await ObsidianVaultLayout.ResolveProjectFolderNameAsync(repo.Root);
        var notePath = FindNote(vaultRoot, repoName, "has-metrics");
        Assert.NotNull(notePath);

        // Simulate operator deleting the note from the vault.
        File.Delete(notePath);
        Assert.False(File.Exists(notePath));

        // Second scan: must NOT re-create the deleted note.
        await Dispatcher.UIThread.InvokeAsync(viewModel.RunObsidianBridgeScanAsync);

        Assert.Null(FindNote(vaultRoot, repoName, "has-metrics"));
    }

    // ═══════════════════════════════════════════════════════════════════
    // Fresh vault (no ledger, no notes): full back-fill
    // ═══════════════════════════════════════════════════════════════════

    [AvaloniaFact]
    public async Task FreshVault_NoLedger_NoNotes_BackfillsAllMetricHavingTasks()
    {
        using var repo = TestRepository.Create();
        repo.WriteConfig("true", []);

        // Two metric-having tasks.
        repo.WriteCompletedTask("alpha", "# Alpha\n\nFirst.");
        WriteStageReport(repo.Root, "alpha", 1, "2026-06-15T10:00:00+00:00");

        repo.WriteCompletedTask("beta", "# Beta\n\nSecond.");
        WriteStageReport(repo.Root, "beta", 1, "2026-06-16T12:00:00+00:00");

        // One task with NO stage reports — must NOT be back-filled.
        repo.WriteCompletedTask("no-metrics", "# No Metrics\n\nHand-archived.");

        var vaultRoot = Path.Combine(_scratch, "vault4");
        var env = new DictionaryEnvironmentAccessor();
        var viewModel = CreateViewModel(repo.Root, vaultRoot, env);
        await viewModel.LoadInitialAsync();
        viewModel.ObsidianVaultRoot = vaultRoot;
        viewModel.ObsidianEnabled = true;

        await Dispatcher.UIThread.InvokeAsync(viewModel.RunObsidianBridgeScanAsync);

        var repoName = await ObsidianVaultLayout.ResolveProjectFolderNameAsync(repo.Root);

        // DESIRED: metric-having tasks get notes (load-bearing back-fill).
        // TODAY: these should exist since the current reconcile back-fills them.
        var alphaNote = FindNote(vaultRoot, repoName, "alpha");
        Assert.NotNull(alphaNote);

        // DESIRED: no-metrics task gets no note — no stage report, no back-fill.
        // TODAY: the current code fabricates a $0.00 note, so this will fail.
        Assert.Null(FindNote(vaultRoot, repoName, "no-metrics"));

        // DESIRED: ledger exists with the two metric-having task ids.
        // TODAY: no ledger code exists, so this will fail.
        var ledgerPath = LedgerPath(vaultRoot, repoName);
        Assert.True(File.Exists(ledgerPath));
    }

    // ═══════════════════════════════════════════════════════════════════
    // Pre-ledger vault (existing notes, no ledger): seed silently
    // ═══════════════════════════════════════════════════════════════════

    [AvaloniaFact]
    public async Task PreLedgerVault_ExistingNotes_SeedsLedger_WritesNoNewNotes()
    {
        using var repo = TestRepository.Create();
        repo.WriteConfig("true", []);

        repo.WriteCompletedTask("existing-task", "# Existing\n\nAlready exported.");
        WriteStageReport(repo.Root, "existing-task", 1, "2026-06-20T08:00:00+00:00");

        var vaultRoot = Path.Combine(_scratch, "vault5");
        var env = new DictionaryEnvironmentAccessor();
        var viewModel = CreateViewModel(repo.Root, vaultRoot, env);
        await viewModel.LoadInitialAsync();
        viewModel.ObsidianVaultRoot = vaultRoot;
        viewModel.ObsidianEnabled = true;

        // Run one scan to populate the vault normally (creates the note).
        await Dispatcher.UIThread.InvokeAsync(viewModel.RunObsidianBridgeScanAsync);

        var repoName = await ObsidianVaultLayout.ResolveProjectFolderNameAsync(repo.Root);
        var notePath = FindNote(vaultRoot, repoName, "existing-task");
        Assert.NotNull(notePath);

        // Delete the ledger (simulating pre-ledger era) but KEEP the note.
        var ledgerPath = LedgerPath(vaultRoot, repoName);
        if (File.Exists(ledgerPath)) File.Delete(ledgerPath);
        Assert.False(File.Exists(ledgerPath));

        // Add a SECOND completed task with metrics — its note does NOT exist
        // in the vault (pre-ledger era, only one was exported).
        repo.WriteCompletedTask("second-task", "# Second\n\nAlso completed.");
        WriteStageReport(repo.Root, "second-task", 1, "2026-06-21T09:00:00+00:00");

        // Scan: pre-ledger vault — must seed ledger silently, NOT write new notes.
        await Dispatcher.UIThread.InvokeAsync(viewModel.RunObsidianBridgeScanAsync);

        // DESIRED: the ledger must exist and contain ALL completed ids.
        // TODAY: no ledger, this fails.
        Assert.True(File.Exists(ledgerPath));

        // DESIRED: the second task must NOT have a note — history is settled.
        // TODAY: old code will back-fill the second task's note, so this fails too.
        Assert.Null(FindNote(vaultRoot, repoName, "second-task"));
    }

    // ═══════════════════════════════════════════════════════════════════
    // Completion-time export records in ledger
    // ═══════════════════════════════════════════════════════════════════

    [AvaloniaFact]
    public async Task ExportSummaryOnCompletion_RecordsTaskIdInLedger()
    {
        using var repo = TestRepository.Create();
        repo.WriteConfig("true", []);
        repo.WriteTask("drain-me", "# Drain Me\n\nRun through drain.");
        WriteStageReport(repo.Root, "drain-me", 1, "2026-06-22T10:00:00+00:00");

        var vaultRoot = Path.Combine(_scratch, "vault6");
        var env = new DictionaryEnvironmentAccessor();
        var viewModel = CreateViewModel(repo.Root, vaultRoot, env);
        await viewModel.LoadInitialAsync();

        // Run one scan first to seed the scaffold and establish the repo name.
        viewModel.ObsidianVaultRoot = vaultRoot;
        viewModel.ObsidianEnabled = true;
        await Dispatcher.UIThread.InvokeAsync(viewModel.RunObsidianBridgeScanAsync);

        var repoName = await ObsidianVaultLayout.ResolveProjectFolderNameAsync(repo.Root);

        // Drive the drain lifecycle — OnExecuteCompleted fires ExportSummaryOnCompletion.
        var callbacks = viewModel.CreateDrainLifecycleCallbacks();
        callbacks.OnExecuteStarted!("drain-me");
        var outcome = new RelayTaskOutcome(
            "drain-me", RelayTaskOutcomeStatus.Committed, "hash", "abc1234", null);
        callbacks.OnExecuteCompleted!("drain-me", outcome);

        // Wait for the fire-and-forget export to land.
        await TestWaits.ForFileAsync(
            Path.Combine(vaultRoot, repoName, "Completed"),
            predicate: () => FindNote(vaultRoot, repoName, "drain-me") is not null);

        // DESIRED: the ledger must now contain the task id.
        // TODAY: ExportSummaryOnCompletion doesn't touch a ledger — fails.
        var ledgerPath = LedgerPath(vaultRoot, repoName);
        Assert.True(File.Exists(ledgerPath));
    }

    // ═══════════════════════════════════════════════════════════════════
    // Corrupt ledger: treated as absent, seeding rules apply, no crash
    // ═══════════════════════════════════════════════════════════════════

    [AvaloniaFact]
    public async Task CorruptLedger_TreatedAsAbsent_NoCrash()
    {
        using var repo = TestRepository.Create();
        repo.WriteConfig("true", []);
        repo.WriteCompletedTask("corrupt-test", "# Corrupt\n\nTest.");
        WriteStageReport(repo.Root, "corrupt-test", 1, "2026-06-23T10:00:00+00:00");

        var vaultRoot = Path.Combine(_scratch, "vault7");
        var env = new DictionaryEnvironmentAccessor();
        var viewModel = CreateViewModel(repo.Root, vaultRoot, env);
        await viewModel.LoadInitialAsync();
        viewModel.ObsidianVaultRoot = vaultRoot;
        viewModel.ObsidianEnabled = true;

        // First scan — creates the vault scaffold and, after the fix, the ledger.
        await Dispatcher.UIThread.InvokeAsync(viewModel.RunObsidianBridgeScanAsync);

        var repoName = await ObsidianVaultLayout.ResolveProjectFolderNameAsync(repo.Root);

        // Write a corrupt ledger file.
        var ledgerPath = LedgerPath(vaultRoot, repoName);
        Directory.CreateDirectory(Path.GetDirectoryName(ledgerPath)!);
        await File.WriteAllTextAsync(ledgerPath, "this is not valid json {{{ corrupted");

        // Second scan must not crash (the ledger is corrupt, treat as absent).
        await Dispatcher.UIThread.InvokeAsync(viewModel.RunObsidianBridgeScanAsync);

        // After the fix, the corrupt ledger would be replaced with valid JSON.
        // Today: stale corrupt file sits untouched — JsonDocument.Parse will throw.
        // That exception is the RED test: the ledger isn't being managed yet.
        var bytes = await File.ReadAllBytesAsync(ledgerPath);
        using var doc = JsonDocument.Parse(bytes);
        Assert.NotNull(doc);
    }
}

