public async Task CorruptLedger_TreatedAsAbsent_NoCrash()
{
    using var repo = TestRepository.Create();
    repo.WriteConfig("true", []);

    // Task A: has metrics, will get its note via first-scan back-fill.
    repo.WriteCompletedTask("task-a", "# Task A\n\nFirst.");
    WriteStageReport(repo.Root, "task-a", 1, "2026-06-23T10:00:00+00:00");

    var vaultRoot = Path.Combine(_scratch, "vault7");
    var env = new DictionaryEnvironmentAccessor();
    var viewModel = CreateViewModel(repo.Root, vaultRoot, env);
    await viewModel.LoadInitialAsync();

    // First scan — creates the vault scaffold and the note for task-a.
    await Dispatcher.UIThread.InvokeAsync(viewModel.RunObsidianBridgeScanAsync);

    var repoName = await ObsidianVaultLayout.ResolveProjectFolderNameAsync(repo.Root);

    // Write a corrupt ledger file (simulating a damaged ledger from a prior run).
    var ledgerPath = LedgerPath(vaultRoot, repoName);
    // ledgerPath's parent dir was already created by the scan's scaffold.
    await File.WriteAllTextAsync(ledgerPath, "this is not valid json {{{ corrupted");

    // Delete task-a's note to simulate operator deletion.
    var noteA = FindNote(vaultRoot, repoName, "task-a");
    if (noteA is not null) File.Delete(noteA);

    // Also add a second task that has metrics but NO note in the vault.
    repo.WriteCompletedTask("task-b", "# Task B\n\nSecond.");
    WriteStageReport(repo.Root, "task-b", 1, "2026-06-24T11:00:00+00:00");

    // Second scan: with a corrupt ledger → treated as absent → seeding rules.
    // Vault has existing notes from other tasks: pre-ledger → seal, don't back-fill.
    // TODAY: the old File.Exists dedupe re-creates task-a (defect 3) AND
    // back-fills task-b (because File.Exists says "no note"). The test asserts
    // NEITHER should appear — the run must not crash.
    await Dispatcher.UIThread.InvokeAsync(viewModel.RunObsidianBridgeScanAsync);

    // DESIRED: after corrupt-ledger seed, neither task-a nor task-b gets a note.
    // TODAY: old code re-creates both — these assertions will fail.
    Assert.Null(FindNote(vaultRoot, repoName, "task-a"));
    Assert.Null(FindNote(vaultRoot, repoName, "task-b"));
}

